// Input Validation Logic
const body = $json.body;
if (!body || !body.action) {
  throw new Error('Missing required field: action');
}
if (['runFlow'].includes(body.action) && !body.flowName) {
  throw new Error('Action runFlow requires flowName');
}
return $json;

// runFlow handler - returns processed flow name for reference
const flowName = $json.body.flowName;
const input = $json.body.input;
return { text: `Processed flow ${flowName} with Arkan Logic Engine`, flowName, input };

// retrieveContext handler
const query = $json.body.prompt;
const options = $json.body.options || {};
return { context: [], query, message: 'RAG retrieval via Qdrant', success: true };
